input.command:
sed -i '$d' tests/export_test.sh
cat >> tests/export_test.sh <<'EOF'
out=$(bash bin/export --rows 600 --dry-run)
[ "$(echo "$out" | wc -l)" = 3 ] || { echo "export batch count"; fail=1; }
echo "$out" | grep -q 'rows=1-250 ' || { echo "export batch size 250"; fail=1; }
echo "$out" | grep -q 'rows=501-600 ' || { echo "export remainder"; fail=1; }
echo "$out" | grep -q ' X-Relay-Key$' || { echo "export auth header"; fail=1; }
echo "$out" | grep -q 'X-Partner-Token' && { echo "export old header"; fail=1; }
exit $fail
EOF
sed -i '0,/^## 3.4.1/s//## Unreleased\n\n- export: batches are 250 rows (ADR-0012) and the auth header is `X-Relay-Key`; fixes the 413\/401 failures (RLY-748)\n\n## 3.4.1/' CHANGELOG.md
bash scripts/verify.sh; head -9 CHANGELOG.md; git diff HEAD --stat
